// EXP-328 · EXP-308-v1: minimal video benchmark on one fixed unit (the first two scenes of a Reels script).
//   Path B (no Higgsfield): a text model writes an animated HTML/CSS page, the platform renders it
//           (Playwright seeks every CSS animation to each frame, FFmpeg encodes), cost = text only.
//   Path A (Higgsfield): clips generated by video models are added from a manifest and judged the same way.
// Candidates are judged blind (shuffled labels, 4 frames each at the same fractions of the video) by two vision
// models of other families; they score 1–5 on script adherence, legibility and brand identity. Four frames do
// not measure motion: that limit is part of the method.
//   node --env-file=.env scripts/lab-video.mjs write  [--budget 0.5]       → path B: write, render, save
//   node --env-file=.env scripts/lab-video.mjs judge  [--budget 0.5]       → ingest path A clips, judge all
//   Path A manifest: .runtime/video/a/manifest.json  [{ "model": "kling3_0_turbo", "files": ["a/kling-1.mp4","a/kling-2.mp4"], "credits": 15, "seconds": 60 }]
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";

process.env.MEMORAVEL_DB = "postgres";
const stage = process.argv[2];
const budget = Number(process.argv[process.argv.indexOf("--budget") + 1]) || 0.5;
const DIR = path.resolve(".runtime/video");
const { createLabStore, startRound } = await import("../server/lab.mjs");
const { createObservability } = await import("../server/observability.mjs");
const { benchmarkModel, routingPolicy } = await import("../server/ai.mjs");
const { closePool } = await import("../server/sql.mjs");
const { chromium } = await import("playwright");

const RUN = { id: "EXP-308-v1", experiment: "EXP-328", title: "Vídeo · duas cenas do Reels (caminho B, animação por código, e caminho A, Higgsfield)", task: "video" };
const BRIEF = { id: "reels-2-cenas", title: "Reels do Escritório Conecta, cenas 1 e 2", format: "Vídeo curto (Reels)" };
const WRITERS = ["anthropic/claude-sonnet-5.5", "anthropic/claude-opus-5.5", "deepseek/deepseek-v4-pro-0813"];
const JUDGES = ["google/gemini-4-argon", "openai/gpt-6.1-sol"];
const FPS = 15;
const ffmpeg = process.env.FFMPEG || "ffmpeg";

// The unit: the first two scenes of the saved Reels script, with the raw asset names written in plain words.
const script = JSON.parse(fs.readFileSync(path.join(DIR, "reels.json"), "utf8"));
const clean = (t) => t.replace(/CARD_TIPOGRAFICO_ESCRITORIO/g, "cartão tipográfico").replace(/CENARIO_TEATRO/g, "cenário de teatro");
const scenes = [...script.body.matchAll(/CENA\s+(\d+)\s*·\s*(\d+)s\s*\nFala:\s*([\s\S]*?)\nDireção:\s*([\s\S]*?)(?=\n\s*CENA\s+\d|$)/g)]
  .slice(0, 2).map((m) => ({ number: Number(m[1]), seconds: Number(m[2]), speech: m[3].trim(), direction: clean(m[4].trim()) }));
const TOTAL = scenes.reduce((n, s) => n + s.seconds, 0);
const palette = { fundo: "#f4f1ee", texto: "#141414", destaque: "#8b1c2b", fonte: "Poppins, 'Segoe UI', Arial, sans-serif" };

if (!routingPolicy()) throw new Error("Esta rodada exige o roteamento com privacidade (MEMORAVEL_PRIVACY não pode ser 'standard').");
const store = createLabStore();
const obs = createObservability(path.resolve(".runtime"));
const round = await startRound(store, { ...RUN, budget_usd: budget, config: { briefs: [BRIEF], writers: WRITERS, judges: JUDGES, unitSeconds: TOTAL, scenes, accounts: [], method: "4 quadros por candidato, juízes cegos de visão; não mede movimento" } });
const shuffle = (list) => list.map((v) => [Math.random(), v]).sort((a, b) => a[0] - b[0]).map(([, v]) => v);
const seek = (name, kind) => obs.instrument(Object.assign(async (system, data, observe) => kind(system, data, observe), { modelName: name }), { route: "lab", runTag: RUN.id, provider: "server" });

// ---------- ffmpeg helpers ----------
const ff = (args) => execFileSync(ffmpeg, ["-y", "-loglevel", "error", ...args], { stdio: "pipe" });
const duration = (file) => Number(execFileSync(ffmpeg.replace(/ffmpeg(\.exe)?$/i, "ffprobe$1"), ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", file]).toString().trim());
function frames(video, outDir) {
  fs.mkdirSync(outDir, { recursive: true });
  const d = duration(video), files = [];
  [0.12, 0.4, 0.65, 0.9].forEach((fraction, i) => {
    const file = path.join(outDir, `q${i + 1}.jpg`);
    ff(["-ss", String(d * fraction), "-i", video, "-frames:v", "1", "-vf", "scale=540:-2", "-q:v", "4", file]);
    files.push(file);
  });
  return { seconds: d, files };
}

// ---------- path B ----------
const writerSystem = `Você é motion designer e programa animações em HTML e CSS. Entregue uma página única que será gravada em vídeo vertical.
Regras técnicas: palco de 1080x1920 px (html e body com margin:0, width:1080px, height:1920px, overflow:hidden). Só CSS: animações com @keyframes e animation-delay para marcar o tempo de cada cena, todas finitas e com animation-fill-mode:both. Nada de JavaScript, <script>, imagens, fontes externas ou links. Tudo o que aparece vem de texto e formas CSS. Duração total do vídeo: ${TOTAL} s, com as cenas nos tempos indicados (a cena 1 começa em 0 s; a cena 2 começa quando a 1 termina).
Direção de arte: use exatamente estas cores e fonte: fundo ${palette.fundo}, texto ${palette.texto}, destaque ${palette.destaque}, fonte ${palette.fonte}. Tipografia grande e legível no celular, com margens seguras de 90 px, e a fala de cada cena aparecendo como legenda curta na parte inferior, no tempo da cena. Siga a direção de cada cena (o que entra, o que é riscado, o que surge, tipo de entrada e saída).
Retorne somente {"html": "<!doctype html>..."} com a página completa.`;

async function writeAndRender() {
  for (const WRITER of WRITERS) await writeAndRenderOne(WRITER);
}
async function writeAndRenderOne(WRITER) {
  const out = path.join(DIR, "b", WRITER.replace(/W+/g, "-"));
  fs.mkdirSync(out, { recursive: true });
  const rel = (f) => `b/${WRITER.replace(/W+/g, "-")}/${f}`;
  const item = await round.call({
    key: `${BRIEF.id}|video|${WRITER}`, role: "video", model: WRITER, briefId: BRIEF.id,
    invoke: async (observe) => {
      const started = performance.now();
      const result = await seek(WRITER, benchmarkModel(WRITER))(writerSystem, { marca: script.brand.name, cenas: scenes, duracaoTotalSegundos: TOTAL }, observe);
      const html = String(result.html || "");
      if (!/@keyframes/.test(html) || /<script/i.test(html)) throw new Error("A animação não veio em CSS puro (faltam @keyframes ou há <script>).");
      fs.writeFileSync(path.join(out, "animacao.html"), html);
      const writeSeconds = (performance.now() - started) / 1000;
      // Render: every CSS animation is paused and moved to the instant of each frame, so the video is exact.
      const renderStart = performance.now();
      const browser = await chromium.launch({ channel: "chrome", headless: true });
      const page = await browser.newPage({ viewport: { width: 1080, height: 1920 } });
      await page.goto("file:///" + path.join(out, "animacao.html").replace(/\\/g, "/"));
      await page.evaluate(() => document.fonts.ready);
      const total = Math.round(TOTAL * FPS);
      const framesDir = path.join(out, "frames");
      fs.rmSync(framesDir, { recursive: true, force: true });
      fs.mkdirSync(framesDir, { recursive: true });
      for (let n = 0; n < total; n++) {
        await page.evaluate((ms) => document.getAnimations().forEach((a) => { a.pause(); a.currentTime = ms; }), (n / FPS) * 1000);
        await page.screenshot({ path: path.join(framesDir, `f${String(n).padStart(4, "0")}.jpg`), type: "jpeg", quality: 88 });
      }
      await browser.close();
      ff(["-framerate", String(FPS), "-i", path.join(framesDir, "f%04d.jpg"), "-c:v", "libx264", "-pix_fmt", "yuv420p", "-vf", "scale=720:-2", path.join(out, "video.mp4")]);
      fs.rmSync(framesDir, { recursive: true, force: true });
      return { path: rel("video.mp4"), html: rel("animacao.html"), writeSeconds: Math.round(writeSeconds), renderSeconds: Math.round((performance.now() - renderStart) / 1000), seconds: TOTAL, fps: FPS };
    },
  });
  console.log(item ? `Caminho B (${WRITER}): ${item.status} · texto US$ ${(item.cost_usd ?? 0).toFixed(4)} · ${item.output?.writeSeconds}s escrevendo + ${item.output?.renderSeconds}s renderizando` : "Caminho B falhou (veja o registro da rodada).");
}

// ---------- judging ----------
const dataUrl = (file) => `data:image/jpeg;base64,${fs.readFileSync(file).toString("base64")}`;
function visionJudge(modelName) {
  return async (system, data, observe) => {
    const content = [{ type: "text", text: data.intro }];
    for (const c of data.candidates) {
      content.push({ type: "text", text: `Candidato ${c.label}: quadros 1 a 4 (do início ao fim do vídeo)` });
      for (const file of c.frames) content.push({ type: "image_url", image_url: { url: dataUrl(file) } });
    }
    const response = await fetch(process.env.MEMORABLE_AI_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${process.env.MEMORABLE_AI_KEY}` },
      signal: AbortSignal.timeout(240000),
      body: JSON.stringify({ model: modelName, messages: [{ role: "system", content: system + " Retorne somente JSON válido (formato json)." }, { role: "user", content }], response_format: { type: "json_object" }, max_tokens: 4000, usage: { include: true }, provider: routingPolicy() }),
    });
    if (!response.ok) throw new Error(`Provedor de IA respondeu HTTP ${response.status}: ${(await response.text()).slice(0, 200)}`);
    const result = await response.json();
    observe?.({ inputTokens: result.usage?.prompt_tokens, outputTokens: result.usage?.completion_tokens, ...(Number.isFinite(result.usage?.cost) ? { cost: result.usage.cost } : {}) });
    return JSON.parse(String(result.choices[0].message.content).replace(/^```(?:json)?\s*/i, "").replace(/```$/, ""));
  };
}
const judgeSystem = `Você é um avaliador cego de vídeo curto. Cada candidato é um vídeo vertical do mesmo roteiro, mostrado em 4 quadros do início ao fim. Não sabe como cada um foi feito. Dê notas de 1 a 5 (inteiros) em: aderencia (o que se vê segue as falas e a direção de cada cena), legibilidade (texto na tela legível e correto, composição limpa no celular) e identidade (cores e tipografia coerentes com a marca informada). Nota baixa para texto ilegível, letras deformadas, elementos que contradizem a direção ou aparência genérica. Retorne {"candidatos":[{"label":"A","aderencia":n,"legibilidade":n,"identidade":n,"motivo":"uma frase"}]} com todos os candidatos.`;

async function ingestAndJudge() {
  // Path A clips from the manifest become items (cost in credits, time as measured when they were made).
  const manifestFile = path.join(DIR, "a", "manifest.json");
  if (fs.existsSync(manifestFile)) {
    for (const entry of JSON.parse(fs.readFileSync(manifestFile, "utf8"))) {
      const files = entry.files.map((f) => path.join(DIR, f));
      if (!files.every((f) => fs.existsSync(f))) { console.log(`  ${entry.model}: clipes ausentes, ignorado.`); continue; }
      const slug = entry.model.replace(/\W+/g, "-");
      const joined = path.join(DIR, "a", `${slug}-unido.mp4`);
      const list = path.join(DIR, "a", `${slug}-lista.txt`);
      fs.writeFileSync(list, files.map((f) => `file '${f.replace(/\\/g, "/")}'`).join("\n"));
      ff(["-f", "concat", "-safe", "0", "-i", list, "-vf", "scale=720:-2,fps=24", "-c:v", "libx264", "-pix_fmt", "yuv420p", "-an", joined]);
      const saved = await round.call({
        key: `${BRIEF.id}|video|${entry.model}`, role: "video", model: entry.model, briefId: BRIEF.id, provider: entry.provider || "higgsfield",
        invoke: async (observe) => { observe({ credits: entry.credits ?? undefined }); return { path: `a/${slug}-unido.mp4`, files: entry.files, seconds: entry.seconds, via: entry.via, prompts: entry.prompts }; },
      });
      // The time that counts is the one the clips took to be made, not the time this ingest took.
      if (saved && saved.seconds !== entry.seconds) await store.saveItem({ ...saved, seconds: entry.seconds });
    }
  }
  const items = (await store.items(RUN.id)).filter((i) => i.role === "video" && i.status === "done" && i.output?.path);
  if (items.length < 2) throw new Error("Precisa de pelo menos 2 candidatos prontos para julgar.");
  const labelled = shuffle(items).map((item, n) => ({ item, label: String.fromCharCode(65 + n) }));
  const candidates = labelled.map(({ item, label }) => ({ label, key: item.key, frames: frames(path.join(DIR, item.output.path), path.join(DIR, "quadros", item.model.replace(/\W+/g, "-"))).files }));
  const intro = `Marca: ${script.brand.name}. Paleta e fonte esperadas: fundo ${palette.fundo}, texto ${palette.texto}, destaque ${palette.destaque}, fonte Poppins. Roteiro (duas cenas):\n${scenes.map((s) => `Cena ${s.number} (${s.seconds}s) fala: "${s.speech}" direção: ${s.direction}`).join("\n")}`;
  const hash = createHash("sha1").update(items.map((i) => i.key).sort().join("|")).digest("hex").slice(0, 8);
  const scores = {};
  for (const judge of JUDGES) {
    const judged = await round.call({
      key: `${BRIEF.id}|juiz-v1|${judge}|${hash}`, role: "juiz", model: judge, briefId: BRIEF.id,
      invoke: async (observe) => seek(judge, visionJudge(judge))(judgeSystem, { intro, candidates }, observe),
    });
    if (!judged) { console.log(`  juiz ${judge} falhou`); continue; }
    for (const row of judged.output?.candidatos || []) {
      const target = labelled.find((l) => l.label === row.label);
      if (target) (scores[target.item.key] ||= {})[judge] = { aderencia: row.aderencia, legibilidade: row.legibilidade, identidade: row.identidade, motivo: row.motivo };
    }
  }
  for (const { item } of labelled) {
    const per = scores[item.key] || {};
    const values = Object.values(per).flatMap((s) => [s.aderencia, s.legibilidade, s.identidade]).filter(Number.isFinite);
    const mean = values.length ? values.reduce((n, v) => n + v, 0) / values.length : null;
    await store.saveItem({ ...item, scores: per, mean });
  }
  const final = await store.items(RUN.id);
  console.log("\n===== RESULTADO =====");
  for (const i of final.filter((x) => x.role === "video").sort((a, b) => (b.mean ?? -1) - (a.mean ?? -1))) {
    const cost = i.provider === "claude-code" ? "sessão do Claude Code (sem custo por chamada)" : i.provider === "higgsfield" ? (Number.isFinite(i.credits) ? `${i.credits} créditos` : "custo a confirmar no console") : `US$ ${(i.cost_usd ?? 0).toFixed(4)}`;
    console.log(`${(i.model.split("/").pop()).padEnd(26)} nota ${i.mean == null ? "—" : i.mean.toFixed(2)} · ${cost} · ${i.seconds ?? "—"} s · ${Object.values(i.scores || {}).map((s) => `${s.aderencia}/${s.legibilidade}/${s.identidade}`).join(" ")}`);
  }
  fs.writeFileSync(path.join(DIR, "resultado.json"), JSON.stringify(final.filter((x) => x.role === "video").map(({ model, provider, mean, scores: s, cost_usd, credits, seconds, output }) => ({ model, provider, mean, scores: s, cost_usd, credits, seconds, output })), null, 2));
}

try {
  if (stage === "write") await writeAndRender();
  else if (stage === "judge") await ingestAndJudge();
  else throw new Error("Use: write ou judge.");
} finally {
  await closePool();
}
